692	     * instalment by instalment (see {@link #accrueInstalmentInterest}), and no late fee. On the day the
693	     * charges were waived (after the day's payments), the fee and interest still unpaid are written off
694	     * (kept as what was waived) and that day ends a period: interest starts again from it on what is
695	     * still owed, and no new fee is charged. A written-off invoice is charged only up to the day it was
696	     * written off.
697	     */
698	    public void accrueLateInterest(List<Payment> payments, BigDecimal taxRate, BigDecimal annualRate,
699	            BigDecimal lateFeeUsd, LocalDate asOf) {
700	        annualRate = lateInterestRate(annualRate);
701	        LocalDate today = writtenOffOn != null && writtenOffOn.isBefore(asOf) ? writtenOffOn : asOf;
702	        this.lateInterest = BigDecimal.ZERO;
703	        this.lateFee = BigDecimal.ZERO;
704	        this.lateWaived = BigDecimal.ZERO;
705	        this.instalmentInterest = List.of();
706	        if (status == InvoiceStatus.SENT && !isCreditNote() && hasPlan()) {
707	            accrueInstalmentInterest(payments, taxRate, annualRate, today);
708	            return;
709	        }
710	        if (status != InvoiceStatus.SENT || isCreditNote() || hasPlan() || dueDate == null
711	                || !today.isAfter(dueDate.plusDays(graceDays()))) {
712	            return;
713	        }
714	        boolean earnsInterest = annualRate != null && annualRate.signum() > 0;
715	        BigDecimal fee = lateFeeUsd == null || lateFeeUsd.signum() <= 0 ? zero()
716	                : lateFeeIn(lateFeeUsd, dueDate.plusDays(graceDays() + 1)).min(lateFeeCap(taxRate)).max(zero());
717	        if (!earnsInterest && fee.signum() <= 0) {
718	            return;
719	        }
720	        record Part(LocalDate on, Long paymentId, BigDecimal amount) {
721	        }
722	        List<Part> inOrder = payments.stream().filter(p -> !p.isReversed())
723	                .flatMap(p -> p.getAllocations().stream().filter(a -> a.getInvoiceId().equals(id))
724	                        .map(a -> new Part(a.getDate() == null ? p.getDate() : a.getDate(), p.getId(), a.getAmount())))
725	                .filter(p -> !p.on().isAfter(today))
726	                .sorted(Comparator.comparing(Part::on).thenComparing(Part::paymentId)).toList();
727	        BigDecimal owed = payableBeforeInterest(taxRate).subtract(retentionReleased(taxRate));
728	        BigDecimal paidInGrace = inOrder.stream().filter(p -> !p.on().isAfter(dueDate.plusDays(graceDays())))
729	                .map(Part::amount).reduce(BigDecimal.ZERO, BigDecimal::add);
730	        if (owed.subtract(paidInGrace).signum() <= 0) {
731	            return;
732	        }
733	        BigDecimal daily = earnsInterest
734	                ? BigDecimal.ONE.add(annualRate.divide(BigDecimal.valueOf(36000), MathContext.DECIMAL128))
735	                : null;
736	        LocalDate overdueOn = dueDate.plusDays(graceDays() + 1);
737	        BigDecimal charged = BigDecimal.ZERO;
738	        BigDecimal unpaidInterest = BigDecimal.ZERO;
739	        BigDecimal unpaidFee = BigDecimal.ZERO;
740	        boolean feeCharged = false;
741	        LocalDate from = dueDate.plusDays(graceDays());
742	        LocalDate waiveOn = interestWaivedOn != null && !interestWaivedOn.isBefore(overdueOn)
743	                && !interestWaivedOn.isAfter(today) ? interestWaivedOn : null;
744	        BigDecimal feeWaived = BigDecimal.ZERO;
745	        BigDecimal interestWaived = BigDecimal.ZERO;
746	        for (Part part : inOrder) {
747	            if (waiveOn != null && part.on().isAfter(waiveOn)) {
748	                if (!feeCharged) {
749	                    unpaidFee = fee;
750	                    feeCharged = true;
751	                }
752	                if (earnsInterest && owed.signum() > 0) {
753	                    BigDecimal earned = interestOn(owed, daily, ChronoUnit.DAYS.between(from, waiveOn));
754	                    charged = charged.add(earned);
755	                    unpaidInterest = unpaidInterest.add(earned);
756	                }
757	                from = waiveOn;
758	                feeWaived = unpaidFee;
759	                interestWaived = unpaidInterest;
760	                unpaidFee = BigDecimal.ZERO;
761	                unpaidInterest = BigDecimal.ZERO;
762	                waiveOn = null;
763	            }
764	            if (!feeCharged && !part.on().isBefore(overdueOn)) {
765	                unpaidFee = fee;
766	                feeCharged = true;
767	            }
768	            BigDecimal toFee = part.amount().min(unpaidFee).max(BigDecimal.ZERO);
769	            unpaidFee = unpaidFee.subtract(toFee);
770	            BigDecimal rest = part.amount().subtract(toFee);
771	            if (earnsInterest && part.on().isAfter(from) && owed.signum() > 0) {
772	                BigDecimal earned = interestOn(owed, daily, ChronoUnit.DAYS.between(from, part.on()));
773	                charged = charged.add(earned);
774	                unpaidInterest = unpaidInterest.add(earned);
775	                from = part.on();
776	            }
