778	            unpaidInterest = unpaidInterest.subtract(toInterest);
779	            owed = owed.subtract(rest.subtract(toInterest));
780	        }
781	        if (waiveOn != null) {
782	            if (earnsInterest && owed.signum() > 0) {
783	                BigDecimal earned = interestOn(owed, daily, ChronoUnit.DAYS.between(from, waiveOn));
784	                charged = charged.add(earned);
785	                unpaidInterest = unpaidInterest.add(earned);
786	            }
787	            from = waiveOn;
788	            feeWaived = feeCharged ? unpaidFee : fee;
789	            interestWaived = unpaidInterest;
790	        }
791	        if (earnsInterest && owed.signum() > 0) {
792	            charged = charged.add(interestOn(owed, daily, ChronoUnit.DAYS.between(from, today)));
793	        }
794	        this.lateFee = fee.subtract(feeWaived);
795	        this.lateInterest = charged.subtract(interestWaived);
796	        this.lateWaived = feeWaived.add(interestWaived);
