808	    private void accrueInstalmentInterest(List<Payment> payments, BigDecimal taxRate, BigDecimal annualRate,
809	            LocalDate today) {
810	        if (annualRate == null || annualRate.signum() <= 0) {
811	            return;
812	        }
813	        record Part(LocalDate on, Long paymentId, BigDecimal amount) {
814	        }
815	        List<Part> inOrder = new ArrayList<>();
816	        payments.stream().filter(p -> !p.isReversed())
817	                .flatMap(p -> p.getAllocations().stream().filter(a -> a.getInvoiceId().equals(id))
818	                        .map(a -> new Part(a.getDate() == null ? p.getDate() : a.getDate(), p.getId(), a.getAmount())))
819	                .filter(p -> !p.on().isAfter(today))
820	                .forEach(inOrder::add);
821	        inOrder.sort(Comparator.comparing(Part::on).thenComparing(Part::paymentId));
822	        if (getInterestSaved().signum() > 0 && !inOrder.isEmpty()) {
823	            // The interest dropped by paying the plan off counts as paid with the payment that settled it.
824	            inOrder.add(new Part(inOrder.get(inOrder.size() - 1).on(), Long.MAX_VALUE, getInterestSaved()));
825	        }
826	        BigDecimal[] left = inOrder.stream().map(Part::amount).toArray(BigDecimal[]::new);
827	        BigDecimal daily = BigDecimal.ONE.add(annualRate.divide(BigDecimal.valueOf(36000), MathContext.DECIMAL128));
828	        List<BigDecimal> charges = new ArrayList<>();
829	        BigDecimal total = BigDecimal.ZERO;
830	        for (Instalment instalment : schedule(taxRate)) {
831	            LocalDate due = instalment.dueDate();
832	            BigDecimal owed = instalment.payment();
833	            boolean late = false;
834	            if (due != null && today.isAfter(due.plusDays(graceDays()))) {
835	                BigDecimal paidInGrace = BigDecimal.ZERO;
836	                for (int j = 0; j < left.length; j++) {
837	                    if (!inOrder.get(j).on().isAfter(due.plusDays(graceDays()))) {
838	                        paidInGrace = paidInGrace.add(left[j]);
839	                    }
840	                }
841	                late = paidInGrace.compareTo(owed) < 0;
842	            }
843	            BigDecimal charged = BigDecimal.ZERO;
844	            BigDecimal unpaidInterest = BigDecimal.ZERO;
845	            LocalDate from = due == null ? null : due.plusDays(graceDays());
846	            for (int j = 0; j < left.length; j++) {
847	                Part part = inOrder.get(j);
848	                if (late && part.on().isAfter(from) && owed.signum() > 0) {
849	                    BigDecimal earned = interestOn(owed, daily, ChronoUnit.DAYS.between(from, part.on()));
850	                    charged = charged.add(earned);
851	                    unpaidInterest = unpaidInterest.add(earned);
852	                    from = part.on();
853	                }
854	                BigDecimal toInterest = left[j].min(unpaidInterest).max(BigDecimal.ZERO);
855	                unpaidInterest = unpaidInterest.subtract(toInterest);
856	                BigDecimal toOwed = left[j].subtract(toInterest).min(owed).max(BigDecimal.ZERO);
857	                owed = owed.subtract(toOwed);
858	                left[j] = left[j].subtract(toInterest).subtract(toOwed);
859	            }
860	            if (late && owed.signum() > 0) {
861	                charged = charged.add(interestOn(owed, daily, ChronoUnit.DAYS.between(from, today)));
862	            }
863	            charges.add(charged.setScale(scale(), RoundingMode.HALF_UP));
864	            total = total.add(charged);
865	        }
866	        this.instalmentInterest = charges;
867	        this.lateInterest = total;
868	    }
