870	    /** The interest the balance earns over the days at the daily growth factor, rounded half up to the cent. */
871	    private BigDecimal interestOn(BigDecimal balance, BigDecimal daily, long days) {
872	        if (days <= 0) {
873	            return zero();
874	        }
875	        return balance.multiply(daily.pow((int) days, MathContext.DECIMAL128).subtract(BigDecimal.ONE))
876	                .setScale(scale(), RoundingMode.HALF_UP);
